function lc_alternate_links():string{$locales=['tr','en','de','fr','es','it','pt','ru','ar','fa','nl','zh','ja','ko'];$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';$base=rtrim(lc_env('APP_URL','https://product.tofidesk.com'),'/');$out='';foreach($locales as $locale)$out.='<link rel="alternate" hreflang="'.$locale.'" href="'.esc($base.$path.'?lang='.$locale).'"/>';return $out.'<link rel="alternate" hreflang="x-default" href="'.esc($base.$path).'"/>';}
