if($path==='/account/reset-password'){ $token=(string)($_GET['token']??$_POST['token']??'');$reset=$token!==''?one('SELECT * FROM password_resets WHERE token_hash=? AND used_at IS NULL AND expires_at>?',[hash('sha256',$token),time()]):null;if($_SERVER['REQUEST_METHOD']==='POST'&&$reset){require_csrf();$pass=(string)($_POST['password']??'');$confirm=(string)($_POST['password_confirm']??'');if(strlen($pass)<12||$pass!==$confirm)throw new RuntimeException('Use matching passwords of at least 12 characters.');q('UPDATE buyers SET password_hash=? WHERE id=?',[password_hash($pass,PASSWORD_DEFAULT),$reset['buyer_id']]);q('UPDATE password_resets SET used_at=? WHERE id=?',[time(),$reset['id']]);header('Location: ./login?reset=1');exit;}if(!$reset)buyer_layout('Reset link expired','<div class="card"><h1>Reset link expired</h1><p class="muted">Request a new link to continue.</p><a class="button" href="./forgot-password">Request new link</a></div>');buyer_layout('Create new password','<div class="card"><h1>Create a new password</h1><form method="post"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="token" value="'.esc($token).'"><label>New password<input type="password" name="password" minlength="12" required></label><label>Confirm password<input type="password" name="password_confirm" minlength="12" required></label><button>Save new password</button></form></div>');}

const LC_ROOT = __DIR__ . '/..';
foreach ([LC_ROOT.'/.env', dirname(LC_ROOT).'/.env'] as $env) if (is_file($env)) foreach (file($env, FILE_IGNORE_NEW_LINES) as $line) if (preg_match('/^([A-Z][A-Z0-9_]*)=(.*)$/', trim($line), $m) && getenv($m[1])===false) putenv($m[1].'='.trim(trim($m[2]), "\"'"));
function lc_env(string $key,string $default=''): string { $value=getenv($key); return $value===false||$value===''?$default:$value; }
function lc_db(): PDO { static $db; if(!$db){$path=lc_env('LICENSE_DB_PATH',LC_ROOT.'/storage/licenses.sqlite'); if(!is_dir(dirname($path))) mkdir(dirname($path),0700,true); $db=new PDO('sqlite:'.$path,null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]); $db->exec('PRAGMA foreign_keys=ON; PRAGMA busy_timeout=5000');} return $db; }
function q(string $sql,array $args=[]): PDOStatement{$s=lc_db()->prepare($sql);$s->execute($args);return $s;}
function one(string $sql,array $args=[]):?array{return q($sql,$args)->fetch()?:null;}
function esc(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function csrf():string{if(session_status()!==PHP_SESSION_ACTIVE)session_start();return $_SESSION['csrf']??=bin2hex(random_bytes(24));}
function require_csrf():void{if(!hash_equals($_SESSION['csrf']??'',(string)($_POST['csrf']??'')))throw new RuntimeException('Invalid request token');}
function sales_schema():void{lc_db()->exec(<<<'SQL'
CREATE TABLE IF NOT EXISTS buyers(id INTEGER PRIMARY KEY,email TEXT NOT NULL UNIQUE COLLATE NOCASE,name TEXT NOT NULL DEFAULT '',password_hash TEXT,locale TEXT NOT NULL DEFAULT 'tr',email_verified_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY,buyer_id INTEGER NOT NULL REFERENCES buyers(id) ON DELETE RESTRICT,reference TEXT NOT NULL UNIQUE,product TEXT NOT NULL,amount_minor INTEGER NOT NULL,currency TEXT NOT NULL,tax_amount_minor INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','paid','failed','refunded','cancelled')),provider TEXT,provider_reference TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,paid_at TEXT);
CREATE TABLE IF NOT EXISTS payment_events(id INTEGER PRIMARY KEY,provider TEXT NOT NULL,event_key TEXT NOT NULL,payload TEXT NOT NULL,signature_valid INTEGER NOT NULL DEFAULT 0,processed_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(provider,event_key));
CREATE TABLE IF NOT EXISTS invoices(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL UNIQUE REFERENCES orders(id) ON DELETE RESTRICT,invoice_number TEXT NOT NULL UNIQUE,customer_name TEXT NOT NULL,customer_email TEXT NOT NULL,currency TEXT NOT NULL,subtotal_minor INTEGER NOT NULL,tax_amount_minor INTEGER NOT NULL,total_minor INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'issued' CHECK(status IN('issued','void')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS support_tickets(id INTEGER PRIMARY KEY,buyer_id INTEGER NOT NULL REFERENCES buyers(id) ON DELETE CASCADE,subject TEXT NOT NULL,message TEXT NOT NULL,admin_reply TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','pending','answered','closed')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS downloads(id INTEGER PRIMARY KEY,buyer_id INTEGER NOT NULL REFERENCES buyers(id) ON DELETE CASCADE,product TEXT NOT NULL,version TEXT NOT NULL,filename TEXT NOT NULL,url TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rate_limits(bucket TEXT PRIMARY KEY,attempts INTEGER NOT NULL DEFAULT 0,window_started_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sales_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS orders_buyer_status ON orders(buyer_id,status,created_at DESC);
CREATE INDEX IF NOT EXISTS payment_events_processed ON payment_events(processed_at,created_at);
SQL
);try{lc_db()->exec('ALTER TABLE buyers ADD COLUMN email_verified_at TEXT');}catch(Throwable $e){}lc_db()->exec("CREATE TABLE IF NOT EXISTS email_verifications(id INTEGER PRIMARY KEY,buyer_id INTEGER NOT NULL REFERENCES buyers(id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,expires_at INTEGER NOT NULL,used_at INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)");try{lc_db()->exec('ALTER TABLE licenses ADD COLUMN buyer_id INTEGER REFERENCES buyers(id) ON DELETE SET NULL');}catch(Throwable $e){}try{lc_db()->exec('ALTER TABLE support_tickets ADD COLUMN admin_reply TEXT NOT NULL DEFAULT \'\'');}catch(Throwable $e){}lc_db()->exec('CREATE INDEX IF NOT EXISTS licenses_buyer ON licenses(buyer_id)');}
function setup():void{lc_db()->exec("CREATE TABLE IF NOT EXISTS admins(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS themes(id INTEGER PRIMARY KEY,name TEXT NOT NULL,locale TEXT NOT NULL DEFAULT 'global',payload TEXT NOT NULL DEFAULT '{}',status TEXT NOT NULL CHECK(status IN('draft','published')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS licenses(id INTEGER PRIMARY KEY,product TEXT NOT NULL DEFAULT 'transport-cms',key_hash TEXT NOT NULL,key_hint TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'active',domain_limit INTEGER NOT NULL DEFAULT 1,theme_id INTEGER REFERENCES themes(id) ON DELETE SET NULL,source TEXT NOT NULL DEFAULT 'manual',purchase_code_hash TEXT UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS domains(id INTEGER PRIMARY KEY,license_id INTEGER NOT NULL REFERENCES licenses(id) ON DELETE CASCADE,domain TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,last_seen_at TEXT,UNIQUE(license_id,domain)); CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY,license_id INTEGER REFERENCES licenses(id) ON DELETE SET NULL,action TEXT NOT NULL,detail TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS purchase_requests(id INTEGER PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL,company TEXT NOT NULL DEFAULT '',message TEXT NOT NULL DEFAULT '',product TEXT NOT NULL DEFAULT 'transport-cms',status TEXT NOT NULL DEFAULT 'new' CHECK(status IN('new','contacted','completed','closed')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS theme_versions(id INTEGER PRIMARY KEY,theme_id INTEGER NOT NULL REFERENCES themes(id) ON DELETE CASCADE,version TEXT NOT NULL,payload TEXT NOT NULL,features TEXT NOT NULL DEFAULT '[]',changelog TEXT NOT NULL DEFAULT '',status TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(theme_id,version)); CREATE TABLE IF NOT EXISTS content_posts(id INTEGER PRIMARY KEY,type TEXT NOT NULL DEFAULT 'blog',slug TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'draft',cover_url TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS content_translations(id INTEGER PRIMARY KEY,post_id INTEGER NOT NULL REFERENCES content_posts(id) ON DELETE CASCADE,locale TEXT NOT NULL,title TEXT NOT NULL,excerpt TEXT NOT NULL DEFAULT '',body TEXT NOT NULL DEFAULT '',seo_title TEXT NOT NULL DEFAULT '',seo_description TEXT NOT NULL DEFAULT '',keywords TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'draft',UNIQUE(post_id,locale));");foreach(["ALTER TABLE themes ADD COLUMN version TEXT NOT NULL DEFAULT '1.0.0'","ALTER TABLE themes ADD COLUMN price_minor INTEGER NOT NULL DEFAULT 14900","ALTER TABLE themes ADD COLUMN license_type TEXT NOT NULL DEFAULT 'single-site'","ALTER TABLE themes ADD COLUMN preview_url TEXT NOT NULL DEFAULT ''","ALTER TABLE themes ADD COLUMN features TEXT NOT NULL DEFAULT '[]'","ALTER TABLE licenses ADD COLUMN buyer_id INTEGER REFERENCES buyers(id) ON DELETE SET NULL","ALTER TABLE theme_versions ADD COLUMN changelog TEXT NOT NULL DEFAULT ''"] as $migration){try{lc_db()->exec($migration);}catch(Throwable $e){}}sales_schema();}
function sales_setting(string $key,string $default=''):string{$row=one('SELECT value FROM sales_settings WHERE key=?',[$key]);return $row['value']??$default;}function host(string $value):string{$value=strtolower(trim($value));$value=preg_replace('#^https?://#','',$value);$value=explode('/',$value,2)[0];$value=preg_replace('/:\d+$/','',$value);if(!preg_match('/^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/',$value))throw new RuntimeException('A valid public domain is required.');return $value;}
function key_parts(string $key):array{if(!preg_match('/^TDL-([0-9]+)-([A-Z0-9]{24})$/',strtoupper(trim($key)),$m))throw new RuntimeException('Invalid licence key format.');return [(int)$m[1],strtoupper($m[2])];}
function issue_key():array{$secret=strtoupper(bin2hex(random_bytes(12)));$id=(int)lc_db()->lastInsertId();return [$id,'TDL-'.$id.'-'.$secret,$secret];}
function api_json():array{$raw=file_get_contents('php://input')?:'';$json=json_decode($raw,true);return is_array($json)?$json:$_POST;}
function reply(array $data,int $status=200):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode($data,JSON_UNESCAPED_SLASHES);exit;}
function rate_limit(string $bucket,int $limit=60,int $window=60):void{$now=time();$row=one('SELECT attempts,window_started_at FROM rate_limits WHERE bucket=?',[$bucket]);if(!$row||$now-(int)$row['window_started_at']>=$window){q('INSERT INTO rate_limits(bucket,attempts,window_started_at) VALUES(?,?,?) ON CONFLICT(bucket) DO UPDATE SET attempts=excluded.attempts,window_started_at=excluded.window_started_at',[$bucket,1,$now]);return;}$attempts=(int)$row['attempts']+1;if($attempts>$limit){header('Retry-After: '.max(1,$window-($now-(int)$row['window_started_at'])));reply(['active'=>false,'error'=>'Rate limit exceeded'],429);}q('UPDATE rate_limits SET attempts=? WHERE bucket=?',[$attempts,$bucket]);}
function licence_api(bool $activate):never{try{$ip=$_SERVER['REMOTE_ADDR']??'unknown';rate_limit(($activate?'activate':'check').':'.$ip);$input=api_json();[$id,$secret]=key_parts((string)($input['license_key']??''));$licence=one('SELECT * FROM licenses WHERE id=?',[$id]);if(!$licence||!password_verify($secret,$licence['key_hash'])||$licence['status']!=='active')throw new RuntimeException('Licence is not active.');$domain=host((string)($input['domain']??''));$bound=one('SELECT id FROM domains WHERE license_id=? AND domain=?',[$id,$domain]);if(!$bound){$count=(int)(one('SELECT count(*) count FROM domains WHERE license_id=?',[$id])['count']??0);if(!$activate||$count>=(int)$licence['domain_limit'])throw new RuntimeException('This domain is not permitted for the licence.');q('INSERT INTO domains(license_id,domain,last_seen_at) VALUES(?,?,datetime(\'now\'))',[$id,$domain]);q('INSERT INTO events(license_id,action,detail) VALUES(?,?,?)',[$id,'domain.activated',$domain]);}else q('UPDATE domains SET last_seen_at=datetime(\'now\') WHERE id=?',[$bound['id']]);$locale=preg_replace('/[^a-z-]/','',strtolower((string)($input['locale']??'global')));$theme=one("SELECT name,locale,payload FROM themes WHERE id=? AND status='published' AND locale IN (?, 'global') ORDER BY locale=? DESC LIMIT 1",[$licence['theme_id'],$locale,$locale]);reply(['active'=>true,'license'=>['product'=>$licence['product'],'domain'=>$domain,'domain_limit'=>(int)$licence['domain_limit']],'theme'=>$theme?['name'=>$theme['name'],'locale'=>$theme['locale'],'payload'=>json_decode($theme['payload'],true)]:null,'checked_at'=>gmdate('c')]);}catch(Throwable $e){reply(['active'=>false,'error'=>$e->getMessage()],422);}}
function envato_verify():never{try{$ip=$_SERVER['REMOTE_ADDR']??'unknown';rate_limit('envato:'.$ip,10,60);$token=lc_env('ENVATO_PERSONAL_TOKEN');if($token==='')throw new RuntimeException('Envato verification is not configured on this server.');$input=api_json();$code=trim((string)($input['purchase_code']??''));if(!preg_match('/^[a-f0-9-]{20,80}$/i',$code))throw new RuntimeException('A valid Envato purchase code is required.');$curl=curl_init('https://api.envato.com/v3/market/author/sale?code='.rawurlencode($code));curl_setopt_array($curl,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$token,'Accept: application/json'],CURLOPT_TIMEOUT=>10,CURLOPT_CONNECTTIMEOUT=>5]);$raw=curl_exec($curl);$status=(int)curl_getinfo($curl,CURLINFO_HTTP_CODE);$error=curl_error($curl);curl_close($curl);if($raw===false||$error!=='')throw new RuntimeException('Envato verification request failed.');$data=json_decode($raw,true);if($status!==200||!is_array($data))throw new RuntimeException('Envato rejected the purchase code.');$buyerEmail=filter_var((string)($data['buyer']??''),FILTER_VALIDATE_EMAIL);$product=mb_substr((string)($data['item']['name']??'transport-cms'),0,180);reply(['verified'=>true,'product'=>$product,'buyer'=>['email'=>$buyerEmail?:null],'verified_at'=>gmdate('c')]);}catch(Throwable $e){reply(['verified'=>false,'error'=>$e->getMessage()],422);}}
function payment_signature_valid(string $provider,array $payload,string $raw):bool{$provider=strtolower($provider);if($provider==='paytr')return isset($payload['hash'])&&hash_equals(paytr_webhook_signature($payload,lc_env('PAYTR_MERCHANT_KEY'),lc_env('PAYTR_MERCHANT_SALT')),(string)$payload['hash']);if($provider==='iyzico')return isset($_SERVER['HTTP_X_IYZICO_SIGNATURE'])&&iyzico_webhook_valid($payload,lc_env('IYZICO_SECRET_KEY'),(string)$_SERVER['HTTP_X_IYZICO_SIGNATURE']);if($provider==='stripe')return stripe_webhook_valid($raw,(string)($_SERVER['HTTP_STRIPE_SIGNATURE']??''),lc_env('STRIPE_WEBHOOK_SECRET'));return false;}
function paytr_webhook_signature(array $p,string $key,string $salt):string{return base64_encode(hash_hmac('sha256',(string)($p['callback_id']??'').(string)($p['merchant_oid']??'').$salt.(string)($p['status']??'').(string)($p['total_amount']??''),$key,true));}
function iyzico_webhook_valid(array $p,string $secret,string $given):bool{$expected=hash_hmac('sha256',$secret.(string)($p['iyziEventType']??'').(string)($p['paymentId']??'').(string)($p['paymentConversationId']??'').(string)($p['status']??''),$secret);return $secret!==''&&$given!==''&&hash_equals($expected,trim($given));}
function stripe_webhook_valid(string $raw,string $header,string $secret):bool{if($raw===''||$header===''||$secret==='')return false;$t=0;$sig=[];foreach(explode(',',$header) as $part){[$k,$v]=array_pad(explode('=',trim($part),2),2,'');if($k==='t'&&ctype_digit($v))$t=(int)$v;if($k==='v1'&&preg_match('/^[a-f0-9]{64}$/i',$v))$sig[]=$v;}if(!$t||abs(time()-$t)>300)return false;$expected=hash_hmac('sha256',$t.'.'.$raw,$secret);foreach($sig as $v)if(hash_equals($expected,$v))return true;return false;}
function payment_webhook(string $provider):never{try{$issuedLicenseKey=null;$ip=$_SERVER['REMOTE_ADDR']??'unknown';rate_limit('webhook:'.$provider.':'.$ip,30,60);$raw=file_get_contents('php://input')?:'';$payload=json_decode($raw,true);if(!is_array($payload))$payload=$_POST;$eventKey=(string)($payload['event_id']??$payload['id']??$payload['merchant_oid']??$payload['paymentId']??'');if($eventKey==='')throw new RuntimeException('Payment event id is required.');$valid=payment_signature_valid($provider,$payload,$raw);q('INSERT OR IGNORE INTO payment_events(provider,event_key,payload,signature_valid) VALUES(?,?,?,?)',[$provider,$eventKey,json_encode($payload),$valid?1:0]);if(!$valid)throw new RuntimeException('Invalid payment signature.');$status=strtolower((string)($payload['status']??$payload['payment_status']??$payload['event_type']??''));$reference=(string)($payload['order_reference']??$payload['merchant_oid']??$payload['paymentConversationId']??'');$order=$reference!==''?one('SELECT * FROM orders WHERE reference=?',[$reference]):null;if($order&&in_array($status,['paid','success','succeeded','completed'],true)){q("UPDATE orders SET status='paid',paid_at=datetime('now'),provider=?,provider_reference=? WHERE id=? AND status<>'paid'",[$provider,$eventKey,$order['id']]);$buyer=one('SELECT name,email FROM buyers WHERE id=?',[$order['buyer_id']]);if(!$buyer)throw new RuntimeException('Buyer record not found for order.');if(!one('SELECT id FROM invoices WHERE order_id=?',[$order['id']]))q('INSERT INTO invoices(order_id,invoice_number,customer_name,customer_email,currency,subtotal_minor,tax_amount_minor,total_minor) VALUES(?,?,?,?,?,?,?,?,?)',[$order['id'],'INV-'.date('Y').'-'.$order['id'],$buyer['name'],$buyer['email'],$order['currency'],$order['amount_minor'],$order['tax_amount_minor'],$order['amount_minor']+$order['tax_amount_minor']]);if(!one('SELECT id FROM licenses WHERE source=? AND purchase_code_hash=?',[$provider,hash('sha256',$eventKey)])){q('INSERT INTO licenses(product,key_hash,key_hint,status,domain_limit,source,purchase_code_hash,buyer_id) VALUES(?,?,?,?,?,?,?,?)',[$order['product'],'pending','PAY-'.$order['id'],'active',1,$provider,hash('sha256',$eventKey),$order['buyer_id']]);[$licenseId,$issuedLicenseKey,$licenseSecret]=issue_key();q('UPDATE licenses SET key_hash=?,key_hint=? WHERE id=?',[password_hash($licenseSecret,PASSWORD_DEFAULT),'TDL-'.$licenseId,$licenseId]);$downloadUrl=trim(lc_env('PRODUCT_DOWNLOAD_URL'));if($downloadUrl!==''&&filter_var($downloadUrl,FILTER_VALIDATE_URL)&&!one('SELECT id FROM downloads WHERE buyer_id=? AND product=?',[$order['buyer_id'],$order['product']]))q('INSERT INTO downloads(buyer_id,product,version,filename,url) VALUES(?,?,?,?,?)',[$order['buyer_id'],$order['product'],(string)lc_env('PRODUCT_VERSION','1.0.0'),(string)lc_env('PRODUCT_FILENAME','tofidesk-package.zip'),$downloadUrl]);}}reply(['accepted'=>true,'idempotent'=>true,'event_id'=>$eventKey,'license_key'=>$issuedLicenseKey]);}catch(Throwable $e){reply(['accepted'=>false,'error'=>$e->getMessage()],422);}}
function lc_public_locale():string{$supported=['tr','en','de','fr','es','it','pt','ru','ar','fa','nl','zh','ja','ko'];$requested=strtolower((string)($_GET['lang']??''));if(in_array($requested,$supported,true)){setcookie('lc_locale',$requested,['expires'=>time()+31536000,'path'=>'/','secure'=>!empty($_SERVER['HTTPS']),'httponly'=>true,'samesite'=>'Lax']);return $requested;}if(!empty($_SESSION['buyer'])){$account=one('SELECT locale FROM buyers WHERE id=?',[(int)$_SESSION['buyer']]);$accountLocale=strtolower((string)($account['locale']??''));if(in_array($accountLocale,$supported,true))return $accountLocale;}$cookie=strtolower((string)($_COOKIE['lc_locale']??''));if(in_array($cookie,$supported,true))return $cookie;foreach(explode(',',(string)($_SERVER['HTTP_ACCEPT_LANGUAGE']??'')) as $part){$guess=strtolower(substr(trim($part),0,2));if(in_array($guess,$supported,true))return $guess;}return 'tr';}
function lc_public_meta(string $lang,string $title):array{$descriptions=['tr'=>'Taşımacılık işletmeleri için çok dilli web sitesi, tema ve lisans platformu.','en'=>'Multilingual website, theme and licence platform for transport businesses.','de'=>'Mehrsprachige Website-, Theme- und Lizenzplattform für Transportbetriebe.','fr'=>'Plateforme multilingue de sites, thèmes et licences pour le transport.','es'=>'Plataforma multilingüe de sitios, temas y licencias para empresas de transporte.','it'=>'Piattaforma multilingue per siti, temi e licenze di trasporto.','pt'=>'Plataforma multilíngue de sites, temas e licenças para transportes.','ru'=>'Многоязычная платформа сайтов, тем и лицензий для транспортного бизнеса.','ar'=>'منصة متعددة اللغات للمواقع والقوالب والتراخيص لشركات النقل.','fa'=>'پلتفرم چندزبانه سایت، قالب و مجوز برای کسب‌وکارهای حمل‌ونقل.','nl'=>'Meertalig platform voor websites, thema’s en licenties voor transportbedrijven.','zh'=>'面向运输企业的多语言网站、主题和许可证平台。','ja'=>'運送事業者向けの多言語サイト、テーマ、ライセンスプラットフォーム。','ko'=>'운송 기업을 위한 다국어 웹사이트, 테마 및 라이선스 플랫폼.'];$desc=$descriptions[$lang]??$descriptions['tr'];return [$title.' · TofiDesk',$desc];}
function logged_in():bool{return !empty($_SESSION['admin']);}
function login_required():void{if(!logged_in()){header('Location: ./login');exit;}}
function buyer():?array{return !empty($_SESSION['buyer'])?one('SELECT * FROM buyers WHERE id=?',[(int)$_SESSION['buyer']]):null;}
function buyer_required():array{$buyer=buyer();if(!$buyer){header('Location: ./account/login');exit;}return $buyer;}
