if($path==='/content'){if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$slug=preg_replace('/[^a-z0-9-]+/','-',strtolower(trim((string)($_POST['slug']??''))));$type=in_array($_POST['type']??'', ['blog','news','guide'],true)?$_POST['type']:'blog';$locale=substr(strtolower(trim((string)($_POST['locale']??'tr'))),0,8);$status=($_POST['status']??'draft')==='published'?'published':'draft';q('INSERT INTO content_posts(type,slug,status) VALUES(?,?,?)',[$type,$slug,$status]);$id=(int)lc_db()->lastInsertId();q('INSERT INTO content_translations(post_id,locale,title,excerpt,body,seo_title,seo_description,keywords,status) VALUES(?,?,?,?,?,?,?,?,?)',[$id,$locale,trim((string)($_POST['title']??'')),trim((string)($_POST['excerpt']??'')),trim((string)($_POST['body']??'')),trim((string)($_POST['seo_title']??'')),trim((string)($_POST['seo_description']??'')),trim((string)($_POST['keywords']??'')),$status]);header('Location: ./content');exit;}$rows='';foreach(q('SELECT p.*,t.locale,t.title FROM content_posts p LEFT JOIN content_translations t ON t.post_id=p.id ORDER BY p.id DESC')->fetchAll() as $post)$rows.='<tr><td>'.esc($post['type']).'</td><td><strong>'.esc($post['title']??'').'</strong><br><small>'.esc($post['locale']??'').'/'.esc($post['slug']).'</small></td><td>'.esc($post['status']).'</td></tr>';layout('Content centre','<div class="grid"><form class="card" method="post"><input type="hidden" name="csrf" value="'.csrf().'"><h2>New article, news or guide</h2><select name="type"><option value="blog">Blog</option><option value="news">News</option><option value="guide">Guide</option></select><input name="slug" required placeholder="seo-slug"><select name="locale"><option>tr</option><option>en</option><option>de</option><option>fr</option><option>es</option><option>it</option><option>pt</option><option>nl</option><option>ru</option><option>ar</option><option>zh</option><option>ja</option><option>ko</option><option>fa</option></select><input name="title" required placeholder="Title"><input name="excerpt" placeholder="Excerpt"><textarea name="body" required placeholder="Content"></textarea><input name="seo_title" placeholder="SEO title"><textarea name="seo_description" placeholder="SEO description"></textarea><input name="keywords" placeholder="Keywords"><select name="status"><option value="draft">Draft</option><option value="published">Publish</option></select><button>Save content</button></form><section class="card"><h2>Content library</h2><table><tr><th>Type</th><th>Title</th><th>Status</th></tr>'.$rows.'</table></section></div>');}
if($path==='/settings'){login_required();$keys=['brand_name','default_locale','currency','analytics_id','google_verification','meta_verification','pinterest_verification'];if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();foreach($keys as $key){$value=trim((string)($_POST[$key]??''));if($key==='default_locale'&&!in_array($value,['tr','en','de','fr','es','it','pt','ru','ar','fa','nl','zh','ja','ko'],true))$value='tr';if($key==='currency'&&!preg_match('/^[A-Z]{3}$/',$value))$value='EUR';if($key==='analytics_id'&&!preg_match('/^G-[A-Z0-9]+$/',$value))$value='';q('INSERT INTO sales_settings(key,value,updated_at) VALUES(?,?,CURRENT_TIMESTAMP) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=CURRENT_TIMESTAMP',[$key,$value]);}header('Location: ./settings?saved=1');exit;}$fields='';foreach($keys as $key)$fields.='<label>'.esc(ucwords(str_replace('_',' ',$key))).'<input name="'.esc($key).'" value="'.esc(sales_setting($key,$key==='default_locale'?'tr':($key==='currency'?'EUR':''))).'"></label>';layout('Sales settings','<form class="card" method="post"><input type="hidden" name="csrf" value="'.csrf().'"><h2>Sales centre settings</h2><p class="muted">Public metadata and storefront defaults. Secrets and payment credentials stay in the private environment.</p>'.$fields.'<button>Save settings</button></form>');}$stats=one('SELECT (SELECT count(*) FROM licenses) licences,(SELECT count(*) FROM domains) domains,(SELECT count(*) FROM themes WHERE status=\'published\') themes');layout('Dashboard','<div class="card"><h2>Licence service</h2><p>Active licences: '.(int)$stats['licences'].' · Bound domains: '.(int)$stats['domains'].' · Published themes: '.(int)$stats['themes'].'</p><p>Orders: '.(int)$stats['orders'].' · Paid revenue: '.esc(number_format(((int)$stats['revenue'])/100,2)).' · Downloads: '.(int)$stats['downloads'].' · Webhook errors: '.(int)$stats['webhook_errors'].'</p><p>Use the Themes page to publish a signed data-only theme and Licences to issue a domain-limited key.</p></div>');
if($path==='/checkout'){ $buyer=buyer_required(); $plans=['Starter'=>[14900,1],'Studio'=>[29900,3],'Agency'=>[59900,10]]; $plan=(string)($_GET['plan']??$_POST['plan']??'Starter'); if(!isset($plans[$plan]))$plan='Starter'; [$amount,$limit]=$plans[$plan]; if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$reference='TD-'.date('YmdHis').'-'.bin2hex(random_bytes(4));q('INSERT INTO orders(buyer_id,reference,product,amount_minor,currency,status,provider) VALUES(?,?,?,?,?,?,?)',[$buyer['id'],$reference,'TofiDesk '.$plan,$amount,'EUR','pending','test']);buyer_layout('Order created','<div class="card"><h1>Order created</h1><p>Your order <strong>'.esc($reference).'</strong> is pending.</p><p class="muted">Payment provider is in test mode. Configure PayTR, iyzico or Stripe before collecting live payments.</p><a class="button" href="./account">Open buyer dashboard</a></div>');} buyer_layout('Checkout','<div class="card"><h1>Checkout · '.esc($plan).'</h1><p>Amount: <strong>€'.number_format($amount/100,2).'</strong> · Domain limit: '.(int)$limit.'</p><p class="muted">No live payment key is configured, so this creates a test-mode pending order only.</p><form method="post"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="plan" value="'.esc($plan).'"><button>Create test-mode order</button></form></div>');}
if($path==='/pricing'){$plans=[['Starter','149','1 domain','Single-site licence','Core CMS, 14-language foundation, quote forms'],['Studio','299','3 domains','Multi-site licence','All themes, SEO centre, AI workflow, priority updates'],['Agency','599','10 domains','Agency licence','White-label delivery, theme customisation, extended support']];$cards='';foreach($plans as [$name,$price,$domains,$licence,$features])$cards.='<article class="card"><span class="eyebrow">'.esc($licence).'</span><h2>'.esc($name).'</h2><p style="font-size:38px;font-weight:800;color:#08283a">'.esc(sales_setting('currency','EUR')).' '.esc($price).'<small style="font-size:14px"> one-time</small></p><p>'.esc($domains).'</p><p style="margin-top:16px">✓ '.esc($features).'</p><a class="button" style="margin-top:22px" href="./contact?plan='.rawurlencode($name).'">Choose '.esc($name).' →</a></article>';layout('Pricing and licences','<section class="hero"><span class="eyebrow">Clear licensing for transport businesses</span><h1>Choose the delivery plan that fits your team.</h1><p>Every plan includes the installable CMS, secure licence activation and future-compatible theme delivery. Payment is handled after your purchase request is reviewed.</p></section><section class="grid">'.$cards.'</section><h2 class="section-title">Feature comparison</h2><div class="card"><table><tr><th>Feature</th><th>Starter</th><th>Studio</th><th>Agency</th></tr><tr><td>Public site and admin</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td>14 languages and RTL</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td>Theme library</td><td>Core</td><td>All themes</td><td>All themes</td></tr><tr><td>Allowed domains</td><td>1</td><td>3</td><td>10</td></tr><tr><td>Priority support</td><td>—</td><td>✓</td><td>✓</td></tr><tr><td>White-label delivery</td><td>—</td><td>—</td><td>✓</td></tr></table></div>',true);}
